from importlib.metadata import pass_none
from itertools import combinations_with_replacement

from taf.config.testline.testline import TestLine
from taf.config.testline import CUS, Simulator

from taf.ul.sc import perf
from taf.ul.sc.perf.testline import PerformanceTestLine
from taf.ul.sc.perf.testline.generator import TestLineGenerator
from taf.ul.sc.perf.util.robot_helpers import get_builtin_value, set_suite_variable

from taf.ul.sc.perf.util.logger import log_info_to_console

DEFAULT_UTE_CONFIG = {
    'ue': {
        'type': 'CUS',
        'workstation': {
            'host': 'localhost',
            'login': 'ute',
            'password': 'ute',
            'root_password': 'ute'
        }
    },
    'btss': []
}


class TestLineLoader(object):
    """
    Load test line configuration.
    Interface to robot. Used only for functional test which not used 'Run Procedure' Keyword
    It should be imported as first library
    Usage:
        Library    taf.ul.sc.perf.testline.TestLineLoader
    """

    def __init__(self, default_configuration=False, autoload=True):
        if autoload:
            if default_configuration:
                self._load_default_test_line_configuration()
            else:
                self._load_test_line_configuration()

    def load_default_configuration(self, host=None, login=None, password=None, root_password=None):
        for name, value in {'host': host, 'login': login, 'password': password, 'root_password': root_password}.items():
            if value is not None:
                DEFAULT_UTE_CONFIG['ue']['workstation'][name] = value
        self._load_default_test_line_configuration()

    def dummy_kw(self):
        pass

    def _load_test_line_configuration(self):
        if not perf.tl:
            self._generate_test_line_configuration()

    def _generate_test_line_configuration(self):
        # there is possibility to define testline dictionary with name tl_config or tl
        # additionally taf team requested to put tl_config into taf tl variable so it is checked if not defined this way
        tl_config = get_builtin_value('tl_config', None)
        if not tl_config:
            tl_config = get_builtin_value('tl')

            if hasattr(tl_config, 'tl_config'):
                tl_config = tl_config.tl_config
            elif tl_config is not None and isinstance(tl_config, TestLine):
                tl_config = self.generate_config(tl_config)

        if tl_config and isinstance(tl_config, dict):
            ptlg = TestLineGenerator(conf=tl_config)
            ptlg.generate_test_line()
            tl = ptlg.tl
        else:
            tl = tl_config
        self._set_tl(tl_obj=tl)

    def generate_config(self, tl_config):
        """
        Generate test line configuration dictionary from UTE test line configuration object
        :param tl_config: UTE test line configuration object
        :return: test line configuration dictionary
        """
        core_type = 'EPCsim'

        config = dict()
        config["btss"] = self._generate_enb_ute_config(tl_config)
        config["ue"] = self._generate_rtg_ute_config(tl_config)
        # TODO: Add core other values than default. To do this we need to get sample of core configuration from UTE
        config["core"] = self._get_core_ute_configuration(core_type)

        config['owner'] = 'IHT'
        config['name'] = "auto_generated_TL"
        config['tl_type'] = 'IHT testline'
        config['maintainers'] = ['IHT']
        return config

    def _generate_enb_ute_config(self, tl_config):
        generated_config = []
        try:
            enbs = tl_config.enbs
            if not enbs:
                enbs = tl_config.gnbs
        except AttributeError:
            log_info_to_console("No eNBs or gNBs defined in test line configuration. Using default configuration.",
                                log_hierarchy=2, add_timestamp=False)
            enbs = []
        if tl_config.test_pcs is None:
            test_pcs = [tl_config.test_pc]
        else:
            test_pcs = tl_config.test_pcs
        enb_hw_type = "AirScaleEnb"  # tl_config.enb_hw_type
        for enb_id, enb in enumerate(enbs):
            enb_config = dict()
            enb_config['type'] = enb_hw_type
            enb_config['lmp_ip'] = "192.168.255.129"
            enb_config['bh_ip'] = "192.168.255.129"  #
            if test_pcs is None:
                test_pc_connections = tl_config.test_pc.default_ssh_connection_details
            else:
                test_pc_connections = test_pcs[enb_id].default_ssh_connection_details if len(
                    test_pcs) > enb_id else None
            enb_config['workstation'] = {
                'host': test_pc_connections.addr if test_pc_connections is not None else "127.0.0.1",
                'login': test_pc_connections.username if test_pc_connections is not None else 'ute',
                'password': test_pc_connections.password if test_pc_connections is not None else 'ute',
                'root_password': 'ute'
            }
            enb_config['syslog'] = True
            generated_config.append(enb_config)
            return generated_config

    def _get_core_ute_configuration(self, core_type: str):
        core_config = dict()
        core_config['type'] = core_type
        core_config['workstation'] = {
            'host': "127.0.0.1",
            'login': 'ute',
            'password': 'ute',
            'root_password': 'ute'
        }
        core_config["cli"] = dict()
        core_config["cli"]['port'] = 20000
        core_config['epcsim_dir'] = "/opt/iphy/latest"
        return core_config

    def _generate_rtg_ute_config(self, tl_config):
        # RTG is not supported yet. Some common RTG configuration is needed
        for connection in tl_config.test_pc.connections:
            ue_config = dict()
            if (hasattr(connection, "device") and
                    (isinstance(connection.device, CUS) or isinstance(connection.device, Simulator))):
                ue_config['type'] = 'CUS'
                ue_config['workstation'] = {
                    'host': tl_config.test_pc.default_ssh_connection_details.addr,
                    'login': tl_config.test_pc.default_ssh_connection_details.username,
                    'password': tl_config.test_pc.default_ssh_connection_details.password,
                    'root_password': 'ute'
                }
                return ue_config
        return None

    @staticmethod
    def _load_default_test_line_configuration():
        ptlg = TestLineGenerator(conf=DEFAULT_UTE_CONFIG)
        ptlg.generate_default_test_line_configuration()

    @staticmethod
    def _set_tl(tl_obj=None):
        if isinstance(tl_obj, PerformanceTestLine):
            perf.tl = tl_obj
            set_suite_variable('tl', tl_obj)
        else:
            perf.tl = get_builtin_value('tl')

        return perf.tl
